data.minimal_example:
Poll<int>? poll = Poll(
  title: 'Sample poll',
  endsAt: DateTime.now().toUtc().add(Duration(days: 5)),
  isEditable: true,
  options: [
    PollOption(id: 1, label: 'Option 1', voteCount: 10),
    PollOption(id: 2, label: 'Option 2', voteCount: 20),
  ],
);
PollVote<int>? vote;
SimplePoll<int>(
  poll: poll,
  vote: vote,
  onVoteChanged: (newVote) {
    poll = poll!.withVoteApplied(previousVote: vote, newVote: newVote);
    vote = newVote;
  },
);
